insert into public.tiles (guild, skill_name, steps, ledger_resources, recipient_guidance, checklist_footer_note)
values ('Forge', 'Design Your Personal Game Piece', '[{"description":"Step 1 — Sketch your design on paper. Before opening any software draw at least one rough sketch of your game piece. What symbol or shape represents you as a maker? Your finished piece must be no larger than 1 inch wide, 1 inch deep, and 2 inches tall.","requiresApproval":false},{"description":"Step 2 — Join the TinkerCAD class and learn the basics. Class code: 2XTJEL26G. Then watch the intro video before you start building.","requiresApproval":false},{"description":"Step 3 — Build your design in TinkerCAD. Place objects, size them while keeping scale, and align them carefully. Use what you learned in the video.","requiresApproval":false},{"description":"Step 4 — Optional: Import a base from Thingiverse or Printables.","requiresApproval":false},{"description":"Step 5 — Check your dimensions in inches. Select your whole model and confirm it is no wider than 1 inch, no deeper than 1 inch, and no taller than 2 inches.","requiresApproval":false},{"description":"Step 6 — Show the teacher your design before printing. Export your STL and get approval before sending to the printer.","requiresApproval":false},{"description":"Step 7 — Print your piece. If the print fails document what went wrong in your patent packet and what you changed for version 2.","requiresApproval":false},{"description":"Step 8 — Upload a photo or video of your finished game piece.","requiresApproval":false}]'::jsonb, '[{"label":"Join TinkerCAD class — code: 2XTJEL26G","url":"https://www.tinkercad.com/joinclass/2XTJEL26G"},{"label":"Open TinkerCAD Template","url":"https://www.tinkercad.com/things/1v3brIkBiqu/edit?returnTo=%2Fclassrooms%2F7CUhdwU3tyT%2Factivities%2FkSIm4lUkPQI&sharecode=DX6LI_t08XwEVWpoDJ2Puk_CeJgr5t7fhARIwRkhF2Q"},{"label":"Open locked base in TinkerCAD","url":"https://www.tinkercad.com/things/1v3brIkBiqu-game-clip2"}]'::jsonb, null, 'This quest can be completed again for bonus WP as you improve your TinkerCAD skills. Each version must be a meaningful improvement, not a re-print.')
on conflict (guild, skill_name) do update set
