insert into public.tiles (guild, skill_name, steps, ledger_resources, recipient_guidance, checklist_footer_note)
values ('Folded Path', 'Design Your Personal Sticker', '[{"description":"Step 1 — Design your sticker in Piskel. Create a pixel art design that represents something that matters to you.","requiresApproval":false},{"description":"Step 2 — Export your design correctly. Use the Export button and save as a zip file — this keeps the layers separate. Do not use screenshot or save image — use Export and zip only.","requiresApproval":false},{"description":"Step 3 — Install Cricut Design Space on your machine. Go to design.cricut.com and download the app for your computer.","requiresApproval":false},{"description":"Step 4 — Import your Piskel design into Cricut Design Space. Open Design Space, create a new project, and upload your exported image file.","requiresApproval":false},{"description":"Step 5 — Set up Print Then Cut. Select your design and choose Print Then Cut as the operation. This tells the Cricut to first print the sticker and then cut around it precisely.","requiresApproval":false},{"description":"Step 6 — Print on sticker paper. Send the design to the classroom printer with sticker paper loaded. Check that the registration marks print clearly — these are the black marks in the corners that the Cricut uses to find the edges.","requiresApproval":false},{"description":"Step 7 — Cut on the Cricut. Load the printed sticker paper onto the Cricut mat and run the cut. Watch it carefully on the first cut to make sure the registration marks are being read correctly. Try to find partners to share the sticker paper with so we don''t waste materials.","requiresApproval":false},{"description":"Step 8 — Upload a photo or video of your finished sticker.","requiresApproval":false}]'::jsonb, '[{"label":"Open Piskel","url":"https://www.piskelapp.com/"},{"label":"Go to design.cricut.com","url":"https://design.cricut.com"}]'::jsonb, null, null)
on conflict (guild, skill_name) do update set
  steps = excluded.steps,
  ledger_resources = excluded.ledger_resources,
  recipient_guidance = excluded.recipient_guidance,
  checklist_footer_note = excluded.checklist_footer_note;

insert into public.tiles (guild, skill_name, steps, checklist_footer_note, recipient_guidance)
values ('Folded Path', 'Design a T-Shirt for Someone In the Room', '[{"description":"Step 1 — Interview your recipient. Before opening any software sit down with the person you are making this for and ask them three questions: What colors do you love? What is something you care about that most people don''t know? If you could wear one image or word every day what would it be? You are listening not designing yet.","requiresApproval":false},{"description":"Step 2 — Sketch your design on paper. Based on what you learned sketch at least two possible designs by hand. Show both to your recipient and ask which feels more like them. Let their answer change your design.","requiresApproval":false},{"description":"Step 3 — Install Cricut Design Space. Go to design.cricut.com and download the app for your device. Create a free account if you don''t have one.","requiresApproval":false},{"description":"Step 4 — Watch the t-shirt tutorial video. Pay attention to how iron-on vinyl direction works — this is the step most people get wrong.","requiresApproval":false,"resourceUrl":"https://www.youtube.com/watch?v=vdVMdhtRL7w","resourceLabel":"Watch t-shirt tutorial here"},{"description":"Step 5 — Build your design in Cricut Design Space. Create a new project and build your design from your sketch. Keep it simple — one strong image or word reads better than something complicated. Mirror your design before cutting — this is essential for iron-on vinyl.","requiresApproval":false},{"description":"Step 6 — Cut your design. Load your iron-on vinyl onto the Cricut mat shiny side down. Select iron-on vinyl as your material.","requiresApproval":false},{"description":"Step 7 — Press your design onto the shirt. Preheat the shirt for ten seconds to remove moisture. Position your design. Apply heat for 30 seconds at medium-high with firm pressure. Peel the carrier sheet while warm. Press again for ten seconds with the carrier sheet back on top.","requiresApproval":false},{"description":"Step 8 — Deliver it. Give the shirt to the person you made it for in person if possible. Take a photo of them receiving it for your patent packet.","requiresApproval":false}]'::jsonb, 'This quest can be completed again for bonus WP with a different recipient. Each version must show a new interview and a new design — not the same design on a different shirt.', null)
on conflict (guild, skill_name) do update set
  steps = excluded.steps,
  checklist_footer_note = excluded.checklist_footer_note,
  recipient_guidance = excluded.recipient_guidance;

insert into public.tiles (guild, skill_name, steps, recipient_guidance, checklist_footer_note)
values ('Void Navigators', 'Make a Profile-Cut Coaster for Someone', '[{"description":"Step 1 — Name your recipient and capture specifics. Before any software, write who you are making this for (person or pet) and at least two details that will shape the profile design — a hobby, a posture, something only you noticed. These notes belong in your plan packet.","requiresApproval":false},{"description":"Step 2 — Sketch the profile and your maker''s mark on paper. Your gift is a flat-profile piece: one clear silhouette or symbol from the side, plus a small maker''s mark that shows you made it. Get a quick teacher check before you build the CAM file.","requiresApproval":false},{"description":"Step 3 — Choose one material. Pick a single stock for this quest (hardwood, plywood, or shop-approved acrylic). Write which material you are using and why it fits your recipient — one material only for this prototype.","requiresApproval":false},{"description":"Step 4 — Build your CAM file for a profile cut. Vector profile for the coaster footprint, include your maker''s mark in the file, and set cut/score for your one material. Keep it coaster-sized — a flat gift, not a sculpture.","requiresApproval":false},{"description":"Step 5 — Test on scrap. Run a test profile cut on scrap of the same material. Check that the silhouette reads, the mark is legible, and edges are safe. Do not skip this step.","requiresApproval":false},{"description":"Step 6 — Cut the final coaster. Run your approved file on the real stock. Sand or finish only as allowed for that material in the shop.","requiresApproval":false},{"description":"Step 7 — Deliver it. Give the coaster to your recipient in person when you can. Take a photo of them with the gift (or holding it) for your patent packet.","requiresApproval":false},{"description":"Step 8 — Upload your delivery photo. Attach the delivery photo to your patent packet. Final submit stays locked until the photo is uploaded.","requiresApproval":false}]'::jsonb, 'Who is this for? A person or a pet counts. Pick someone you know well enough to design a profile silhouette or symbol — a teacher, teammate, family member, or your dog. Write at least two specific details about them before you open any CAM software. Generic coasters are not the goal.', 'Tier 1 — Required (prototype). This is the first of three required Void quests. Stretch and later tiers stay locked until the full guild ships.')
on conflict (guild, skill_name) do update set
  steps = excluded.steps,
  recipient_guidance = excluded.recipient_guidance,
  checklist_footer_note = excluded.checklist_footer_note;

